export function build(materials,info){
 const B=makeBuilder(materials),named=instantiateAsset(B,'aw95',PARTS,materials);
 const mat=new T.Matrix4();
 for(const [name,list]of Object.entries(PRECISE)){const o=named.get(name);mat.fromArray(list).decompose(o.position,o.quaternion,o.scale);}
 for(const [name,[a,b]]of Object.entries(RODS)){const o=named.get(name),va=new T.Vector3(...a),vb=new T.Vector3(...b);o.position.copy(va).add(vb).multiplyScalar(.5);o.quaternion.setFromUnitVectors(new T.Vector3(0,1,0),vb.sub(va).normalize());}
 // Blender要求节点名唯一，网页测试与运动按总成类别名查找。
 for(const o of named.values())o.name=o.name.replace(/^(helicopter-(?:main-blade(?:-assembly)?|tail-blade-assembly|shaft-bearing))\.\d+$/,'$1');
 // 保留GLB的坐标及三角形，只重排顶点和索引，恢复桨叶的展向端圈顺序。
 const orderBlade=geo=>{const p=geo.attributes.position;let lo=Infinity,hi=-Infinity;for(let i=0;i<p.count;i++){lo=Math.min(lo,p.getX(i));hi=Math.max(hi,p.getX(i));}
  const end=x=>{const seen=new Set(),ids=[];for(let i=0;i<p.count;i++)if(Math.abs(p.getX(i)-x)<1e-7){const key=p.getY(i)+','+p.getZ(i);if(!seen.has(key)){seen.add(key);ids.push(i);}}ids.sort((a,b)=>Math.atan2(p.getY(a),p.getZ(a))-Math.atan2(p.getY(b),p.getZ(b)));return Array.from({length:20},(_,i)=>ids[Math.floor(i*ids.length/20)]);};
  const first=end(lo),last=end(hi),chosen=new Set([...first,...last]),order=[...first,...Array.from({length:p.count},(_,i)=>i).filter(i=>!chosen.has(i)),...last],remap=new Uint32Array(p.count);order.forEach((v,i)=>remap[v]=i);
  const g=geo.clone();for(const [key,a]of Object.entries(geo.attributes)){const data=new a.array.constructor(a.array.length);order.forEach((old,i)=>{for(let k=0;k<a.itemSize;k++)data[i*a.itemSize+k]=a.array[old*a.itemSize+k];});g.setAttribute(key,new T.BufferAttribute(data,a.itemSize,a.normalized));}g.setIndex(Array.from(geo.index.array,i=>remap[i]));return g;};
 for(const o of named.values())if(o.name.startsWith('helicopter-main-blade-assembly')){o.children.sort((a,b)=>Number(a.name.startsWith('blade.tip'))-Number(b.name.startsWith('blade.tip')));for(const mesh of o.children)mesh.geometry=orderBlade(mesh.geometry);}
 const part=id=>B.parts.find(p=>p.id===id).group;
 const start=new T.Vector3(.15,1.3,0),end=new T.Vector3(3.3655,1.6,0),axis=end.clone().sub(start).normalize();
 for(const [i,x]of [.6,1.7,2.8].entries()){const support=named.get('helicopter-shaft-bearing'+(i?'.'+i:''));support.position.copy(start).lerp(end,(x-.15)/(3.3655-.15));support.children[0].quaternion.setFromUnitVectors(new T.Vector3(0,0,1),axis);}
 named.get('main-rotor-hub').position.set(0,2.173,0);part('blades').position.set(0,2.173,0);named.get('helicopter-rotating-ring').position.set(0,2.173-.354,0);
 for(const p of B.parts)p.base.copy(p.group.position);
 const hub=named.get('main-rotor-hub'),blades=part('blades'),ring=named.get('helicopter-rotating-ring'),spin=named.get('helicopter-tail-rotor');
 function update(a,e){for(const p of B.parts){p.group.position.copy(p.base).addScaledVector(p.offset,e);p.group.rotation.set(0,0,0);}blades.rotation.y=hub.rotation.y=ring.rotation.y=a*1.8;spin.rotation.z=-a*6.2;}
 // 尾传动轴的双精度端点，供检查读取支承所在轴线。
 return {...B,update,info,inspection:{tailShaft:{start:start.toArray(),end:end.toArray()}}};
}
